import{z as n,x as s,o as e,c as A,q as t,j as o,D as E,d as r,s as B,S as i}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"晶圆装载与预对准","description":"","frontmatter":{"title":"晶圆装载与预对准","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/wafer-load-prealign.md","filePath":"litho/wafer-load-prealign.md","lastUpdated":1791063341000}'),p={name:"litho/wafer-load-prealign.md"};function d(h,a,_,m,c,f){const l=s("Mermaid");return e(),A("div",null,[a[2]||(a[2]=t('<h1 id="晶圆装载与预对准" tabindex="-1">晶圆装载与预对准 <a class="header-anchor" href="#晶圆装载与预对准" aria-label="Permalink to &quot;晶圆装载与预对准&quot;">​</a></h1><div class="epigraph"><p>机械手把片放到预对准器上找缺口，再交给夹盘。缺口误差几角分，精细对准就要用掉行程。</p><footer>—— 硅片切口（notch）与主平边几何见 SEMI M1 硅片规格</footer></div><p><a href="/litho/thermal-airflow-control">上一课</a>维持柜内气候。缺口是进片：FOUP → 机械手 → 预对准 → 夹盘。本课钉装载与预对准，掩模库下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>精细对准传感器视场有限。预对准太差，标记不进窗，这场报错或盲曝。夹盘吸偏、背面颗粒垫高，调平从一开始就歪。把对准失败全写成标记设计，会漏机械。</p><p><span class="marginnote">「notch（切口）」是硅片边缘磨出的一个小圆弧凹口，「flat（平边）」是老式硅片上的一段直边；两者都是晶圆自带的「正北针」，告诉机器哪边朝上、该转到几度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>光学找 notch/flat，旋转到配方角度，再放夹盘。真空吸盘检查泄漏。颗粒：背面清洗课的后果在这里爆发。节拍：装载时间进产能死时间，与双台掩盖相关。</p><p>工程流程：找缺口前先确认片在承台上落座，旋转找边时片不打滑；notch 与 flat 按配方切换判据；真空吸盘建立后查泄漏与卡盘平面度，背面颗粒超标的片在这里被拒收而不是进了曝光腔再返工。</p>',9)),(e(),o(i,null,{default:E(()=>[B(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20FOUP%5B%22FOUP%22%5D%20--%3E%20ROB%5B%22%E6%9C%BA%E6%A2%B0%E6%89%8B%22%5D%0A%20%20ROB%20--%3E%20PRE%5B%22%E7%BC%BA%E5%8F%A3%E9%A2%84%E5%AF%B9%E5%87%86%22%5D%0A%20%20PRE%20--%3E%20CHK%5B%22%E5%A4%B9%E7%9B%98%E7%9C%9F%E7%A9%BA%22%5D%0A%20%20CHK%20--%3E%20ALN%5B%22%E7%B2%BE%E7%BB%86%E5%AF%B9%E5%87%86%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">薄片、翘曲片预对准更难。配方要有翘曲容忍，否则只服务理想硅。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>缺口锁定旋转零点。残余角误差 × 半径 = 边缘切向偏差，精细对准用网格吸收，但标记必须仍在捕获窗。</p><p><span class="marginnote">数字实例：残余角误差 0.01° 看着微不足道，乘上 150 mm 半径就是约 26 µm 的边缘切向偏差——精细对准视场往往只有几十微米量级，这就是「几角分吃掉行程」的算术。</span></p><p><span class="marginnote">常见误区：对准失败就先怪标记设计。若预对准根本没把标记送进传感器视场，再好的标记也扫不到——先分清是「标记不在窗」还是「标记信号差」，再决定改机械还是改图形。</span></p>',5)),(e(),o(i,null,{default:E(()=>[B(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPIN%5B%22%E6%89%BF%E5%8F%B0%E5%B8%A6%E7%89%87%E6%97%8B%E8%BD%AC%E4%B8%80%E5%9C%88%22%5D%20--%3E%20OPT%5B%22%E5%85%89%E5%AD%A6%E4%BC%A0%E6%84%9F%E5%99%A8%E6%B2%BF%E5%BE%84%E5%90%91%E7%9C%8B%E7%89%87%E7%BC%98%22%5D%0A%20%20OPT%20--%3E%20SIG%5B%22%E5%8D%8A%E5%BE%84%E5%87%BA%E7%8E%B0%E5%8F%B0%E9%98%B6%E6%88%96%E7%9B%B4%E8%BE%B9%22%5D%0A%20%20SIG%20--%3E%20ZERO%5B%22%E6%9E%81%E8%A7%92%E8%AF%BB%E6%95%B0%E5%8D%B3%E6%97%8B%E8%BD%AC%E9%9B%B6%E7%82%B9%22%5D%0A%20%20ZERO%20--%3E%20ROT%5B%22%E6%97%8B%E5%88%B0%E9%85%8D%E6%96%B9%E6%A0%87%E8%AE%B0%E6%96%B9%E4%BD%8D%22%5D%0A%20%20ROT%20--%3E%20HAND%5B%22%E4%BA%A4%E5%A4%B9%E7%9B%98%E5%90%B8%E4%BD%8F%22%5D%0A%20%20ZERO%20--%3E%20ERR%5B%22%E6%AE%8B%E4%BD%99%E8%A7%92%E8%AF%AF%E5%B7%AE%E4%B9%98%E5%8D%8A%E5%BE%84%20%3D%20%E5%88%87%E5%90%91%E5%81%8F%E5%B7%AE%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p>预对准器把片缘过一遍光：机械手把片放到可旋转的承台上，光学传感器沿径向看边缘，承台转一圈，半径出现台阶的位置就是 notch（SEMI M1 规定的圆弧切口）或 flat 的直边，极角读数即旋转零点；随后把片旋到配方期望的标记方位，再交夹盘。notch 与 flat 只是信号形状不同——台阶对直边——找零点的算法一致，片型混产时按配方切换判据即可。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写对准标记设计与对准传感器原理——那是精细对准一层的课域；FOUP 与机械手的厂级自动化接口也归联机课。预对准的前提是片缘完整：缺角、崩边或边缘有附加结构的片会在找缺口一步就报错，这类异常片走人工处置，而不是调配方硬扫。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>预对准把精细对准关进视场。</li><li>夹盘真空与背面颗粒是装载质量。</li><li>下一课掩模怎么上：另一只手、另一套夹持。</li><li>出处：对准传感器课；背面清洗课。</li></ul>',5))])}const u=n(p,[["render",d]]);export{T as __pageData,u as default};
